@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService NotificationSvc
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications.OrderByDescending(x => x.Id))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;
    private int _latestId;

    // Runs during SSR *and* when the component becomes interactive.
    // The first call (SSR) populates _notifications so the HTML is meaningful.
    protected override void OnInitialized()
    {
        _notifications = NotificationSvc.GetAll();
        _latestId = _notifications.Count > 0 ? _notifications.Max(n => n.Id) : 0;
    }

    // Called only once after the component is interactive in the browser.
    // PersistentComponentState is not needed here because OnInitialized already
    // re-reads the same singleton; the key point is that the polling loop
    // starts only on this second lifecycle call, never during SSR.
    protected override Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }

        return Task.CompletedTask;
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            var newer = NotificationSvc.GetSince(_latestId);
            if (newer.Count > 0)
            {
                _notifications.AddRange(newer);
                _latestId = newer.Max(n => n.Id);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

